html:
{#- Quotation - Bold / Decor Theme. Branded header, quotation details, items, totals, terms and signature. -#}
{%- set c = frappe.db.get_value("Company", doc.company, ["company_name", "company_logo", "custom_print_logo", "custom_brand_color", "custom_default_siginture", "custom_print_footer", "phone_no", "email", "website"], as_dict=True) or {} -%}
{%- set brand = c.custom_brand_color or ("#6B1E64" if doc.company == "Alter Styling and Decor" else "#C8102E") -%}
{%- set logo = c.custom_print_logo or c.company_logo or ("/private/files/Asset 94c8d5e.png" if doc.company == "Alter Styling and Decor" else None) -%}

{#- Light tint of the brand colour for section rows -#}
{%- set hx = "0123456789abcdef" -%}
{%- set b = brand|lower -%}
{%- if b|length == 7 and b.startswith("#") and (b[1:]|select("in", hx)|list|length == 6) -%}
  {%- set tint = "rgba(%d, %d, %d, 0.10)"|format(hx.index(b[1]) * 16 + hx.index(b[2]), hx.index(b[3]) * 16 + hx.index(b[4]), hx.index(b[5]) * 16 + hx.index(b[6])) -%}
{%- else -%}
  {%- set tint = "#eef0f4" -%}
{%- endif -%}

{#- Dynamic Signer: doc.print_signature -> company default -> Hilina Mulatu -> fallback -#}
{%- set sig = None -%}
{%- if doc.get("print_signature") -%}
  {%- set sig = frappe.db.get_value("Signature", doc.print_signature, ["signature_name", "position", "attach"], as_dict=True) -%}
{%- endif -%}
{%- if not sig and c.get("custom_default_siginture") -%}
  {%- set sig = frappe.db.get_value("Signature", c.custom_default_siginture, ["signature_name", "position", "attach"], as_dict=True) -%}
{%- endif -%}
{%- if not sig -%}
  {%- set sig = frappe.db.get_value("Signature", {"signature_name": "Hilina Mulatu"}, ["signature_name", "position", "attach"], as_dict=True) -%}
{%- endif -%}
{%- set sign_img = sig.attach if sig else None -%}

{#- Dynamic Print Context (Auto-detect columns, subtotals, VAT, Days, Pages, Qty) -#}
{%- set pctx = doc._print_context or (get_print_context(doc) if get_print_context is defined else None) -%}
{%- if not pctx -%}
  {%- set items_list = doc.items or [] -%}
  {%- set has_days = False -%}
  {%- set has_pages = False -%}
  {%- for r in items_list -%}
    {%- if (r.number_of_days or 0)|float > 0 -%}{%- set has_days = True -%}{%- endif -%}
    {%- if (r.number_of_pages or 0)|float > 0 -%}{%- set has_pages = True -%}{%- endif -%}
  {%- endfor -%}
  {%- set show_sub = doc.print_show_section_subtotals if doc.print_show_section_subtotals is not none else True -%}
  {%- set show_days = doc.print_show_number_of_days if doc.print_show_number_of_days else has_days -%}
  {%- set show_pages = doc.print_show_number_of_pages if doc.print_show_number_of_pages else has_pages -%}
  {%- set hide_qty = doc.print_hide_qty if doc.print_hide_qty else False -%}
  {%- set without_vat = doc.print_without_vat if doc.print_without_vat else False -%}
  {%- set cols = 3 -%}
  {%- if not hide_qty -%}{%- set cols = cols + 1 -%}{%- endif -%}
  {%- if show_days -%}{%- set cols = cols + 1 -%}{%- endif -%}
  {%- if show_pages -%}{%- set cols = cols + 1 -%}{%- endif -%}
  {%- set pctx = {
      'show_subtotals': show_sub,
      'show_days': show_days,
      'show_pages': show_pages,
      'hide_qty': hide_qty,
      'without_vat': without_vat,
      'total_columns': cols,
      'title_colspan': cols,
      'subtotal_label_colspan': cols - 1
  } -%}
{%- endif -%}

<style>
  .bd_wrap .bd_head { background: {{ brand }}; }
  .bd_wrap .bd_accent { color: {{ brand }}; }
  .bd_wrap .bd_items th { background: {{ brand }}; }
  .bd_wrap .bd_section td { background: {{ tint }}; color: {{ brand }}; }
  .bd_wrap .bd_sum .bd_grand td { color: {{ brand }}; border-top: 2px solid {{ brand }}; }
  .bd_wrap .bd_thanks { color: {{ brand }}; }
</style>

<div class="bd_wrap">

  <!-- Header -->
  <div class="bd_card">
    <table class="bd_head">
      <tr>
        <td class="bd_head_l">
          <div class="bd_title">{{ _("Quotation") }}</div>
          <div class="bd_sub">
            {{ doc.name }}
            {% if doc.docstatus == 0 %}
              <span class="bd_pill">DRAFT</span>
            {% elif doc.docstatus == 2 %}
              <span class="bd_pill">CANCELLED</span>
            {% endif %}
          </div>
        </td>

        <td class="bd_head_r">
          {% if logo %}
            <span class="bd_logo">
              <img src="{{ logo }}" alt="{{ c.company_name or doc.company }}">
            </span>
          {% else %}
            <span class="bd_company">{{ c.company_name or doc.company }}</span>
          {% endif %}
        </td>
      </tr>
    </table>
  </div>

  <!-- Customer and quotation details -->
  <table class="bd_info">
    <tr>
      <td class="bd_info_l">
        <div class="bd_label bd_accent">{{ _("Quotation To") }}</div>

        <div class="bd_name">
          {{ doc.customer_name or doc.party_name }}
        </div>

        {% if doc.get("contact_display") and doc.contact_display != doc.customer_name %}
          <div>{{ doc.contact_display }}</div>
        {% endif %}

        {% if doc.get("contact_mobile") %}
          <div>{{ _("Phone") }}: {{ doc.contact_mobile }}</div>
        {% endif %}

        {% if doc.get("contact_email") %}
          <div>{{ _("Email") }}: {{ doc.contact_email }}</div>
        {% endif %}

        {% if doc.get("address_display") %}
          <div class="bd_addr">{{ doc.address_display }}</div>
        {% endif %}
      </td>

      <td class="bd_info_r">
        <table class="bd_kv">
          {% if doc.transaction_date %}
          <tr>
            <td>{{ _("Date") }}</td>
            <td>{{ doc.get_formatted("transaction_date") }}</td>
          </tr>
          {% endif %}

          {% if doc.get("valid_till") %}
          <tr>
            <td>{{ _("Valid Till") }}</td>
            <td>{{ doc.get_formatted("valid_till") }}</td>
          </tr>
          {% endif %}

          {% if doc.get("order_type") and doc.order_type != "Sales" %}
          <tr>
            <td>{{ _("Type") }}</td>
            <td>{{ doc.order_type }}</td>
          </tr>
          {% endif %}
        </table>
      </td>
    </tr>
  </table>

  <!-- Service Description / Event Details -->
  {% if doc.get("desc") or doc.get("event_date") or doc.get("event_location") %}
  <div class="bd_desc">
    {% if doc.get("event_date") or doc.get("event_location") %}
      <div style="margin-bottom: 8px;">
        {% if doc.get("event_date") %}
          <span style="margin-right: 18px;"><b>Event Date:</b> {{ doc.get_formatted("event_date") }}</span>
        {% endif %}
        {% if doc.get("event_location") %}
          <span><b>Location:</b> {{ doc.event_location }}</span>
        {% endif %}
      </div>
    {% endif %}
    {% if doc.get("desc") %}
      <div class="bd_label bd_accent">{{ _("Service Description") }}</div>
      {{ doc.desc }}
    {% endif %}
  </div>
  {% endif %}

  <!-- Items -->
  <table class="bd_items">
    <thead>
      <tr>
        <th class="bd_l">{{ _("Item Description") }}</th>
        <th class="bd_r bd_w_price">{{ _("Unit Price") }} ({{ doc.currency }})</th>
        {% if not pctx.hide_qty %}
        <th class="bd_c bd_w_qty">{{ _("Qty") }}</th>
        {% endif %}
        {% if pctx.show_days %}
        <th class="bd_r bd_w_days">{{ _("No. of Days") }}</th>
        {% endif %}
        {% if pctx.show_pages %}
        <th class="bd_r bd_w_pages">{{ _("Pages") }}</th>
        {% endif %}
        <th class="bd_r bd_w_total">{{ _("Total") }} ({{ doc.currency }})</th>
      </tr>
    </thead>

    <tbody>
      {% for row in doc.items %}

        {% if row.get("is_section") or row.item_name == "Separator" or row.item_code == "Separator" %}

          <tr class="bd_section">
            <td colspan="{{ pctx.total_columns }}">
              {{ row.get("section_title") or row.description or row.item_name }}
            </td>
          </tr>

        {% elif row.is_section_subtotal %}

          <tr class="bd_subtotal_row">
            <td colspan="{{ pctx.subtotal_label_colspan }}" class="bd_r bd_bold" style="padding-right: 14px;">
              Subtotal ({{ row.section_title or "" }}):
            </td>
            <td class="bd_r bd_bold">
              {{ "{:,.2f}".format(row.amount or 0) }}
            </td>
          </tr>

        {% else %}

          <tr class="bd_row">
            <td class="bd_l">
              <div class="bd_item">
                {{ row.item_name or row.item_code }}
              </div>

              {% if row.description and row.description|striptags|trim != (row.item_name or "")|trim %}
                <div class="bd_item_desc">
                  {{ row.description }}
                </div>
              {% endif %}
            </td>

            <td class="bd_r">
              {{ "{:,.2f}".format(row.rate or 0) }}
            </td>

            {% if not pctx.hide_qty %}
            <td class="bd_c">
              {{ row.get_formatted("qty", doc) if row.get("qty") is not none else row.get_formatted("quantity", doc) }}

              {% if row.uom and row.uom != "Nos" %}
                <div class="bd_uom">{{ row.uom }}</div>
              {% endif %}
            </td>
            {% endif %}

            {% if pctx.show_days %}
            <td class="bd_r">
              {{ "{:,.2f}".format(row.get("number_of_days") or 0) }}
            </td>
            {% endif %}

            {% if pctx.show_pages %}
            <td class="bd_r">
              {{ "{:,.0f}".format(row.get("number_of_pages") or 0) }}
            </td>
            {% endif %}

            <td class="bd_r bd_bold">
              {{ "{:,.2f}".format(row.amount or 0) }}
            </td>
          </tr>

        {% endif %}

      {% endfor %}
    </tbody>
  </table>

  <!-- Totals -->
  <table class="bd_sum">
    <tr>
      <td>{{ _("Sub-Total") }}</td>
      <td>{{ doc.get_formatted("total") }}</td>
    </tr>

    {% if doc.discount_amount %}
    <tr>
      <td>
        {{ _("Discount") }}
        {% if doc.additional_discount_percentage %}
          ({{ doc.additional_discount_percentage }}%)
        {% endif %}
      </td>
      <td>-{{ doc.get_formatted("discount_amount") }}</td>
    </tr>
    {% if doc.net_total and doc.net_total != doc.total %}
    <tr>
      <td>{{ _("Net Total") }}</td>
      <td>{{ doc.get_formatted("net_total") }}</td>
    </tr>
    {% endif %}
    {% endif %}

    {% if not pctx.without_vat %}
      {% for tax in doc.taxes %}
        {% if tax.tax_amount %}
        <tr>
          <td>
            {{ tax.description }}
            {% if tax.rate %} ({{ tax.rate }}%){% endif %}
          </td>
          <td>{{ tax.get_formatted("tax_amount") }}</td>
        </tr>
        {% endif %}
      {% endfor %}

      <tr class="bd_grand">
        <td>{{ _("Grand Total") }}:</td>
        <td>{{ doc.get_formatted("grand_total") }}</td>
      </tr>
    {% else %}
      <tr class="bd_grand">
        <td>{{ _("Grand Total (excl. VAT)") }}:</td>
        <td>{{ doc.get_formatted("net_total") or doc.get_formatted("total") }}</td>
      </tr>
    {% endif %}
  </table>

  {% if doc.get("in_words") %}
    <div class="bd_words">{{ doc.in_words }}</div>
  {% endif %}

  <!-- Terms and Signature -->
  <table class="bd_bottom">
    <tr>
      <td class="bd_bottom_l">

        {% if doc.terms %}
          <div class="bd_label bd_accent">{{ _("Terms & Conditions") }}</div>
          <div class="bd_terms">{{ doc.terms }}</div>
        {% endif %}

        <div class="bd_thanks">
          {{ _("Thank You For Your Business") }}
        </div>

      </td>

      <td class="bd_bottom_r">

        {% if sign_img or sig %}
        <div class="bd_sign_wrap">

          {% if sign_img %}
            <div class="bd_sign">
              <img src="{{ sign_img }}" alt="">
            </div>
          {% endif %}

          {% if sig %}
            <div class="bd_sign_text">
              <div class="bd_sign_name">
                {{ sig.signature_name }}
              </div>

              {% if sig.position %}
                <div class="bd_sign_pos">{{ sig.position }}</div>
              {% endif %}
            </div>
          {% endif %}

        </div>
        {% endif %}

      </td>
    </tr>
  </table>

</div>

<!-- Company Footer -->
<div id="footer-html" class="visible-pdf">
  <div class="pbd_footer" style="border-top: 3px solid {{ brand }};">

    <b class="pbd_footer_title" style="color: {{ brand }};">
      {{ c.company_name or doc.company }}
    </b>

    {% if c.custom_print_footer %}

      {% for line in c.custom_print_footer.split("\n") if line.strip() %}
        <br>
        {{ line.strip() }}
      {% endfor %}

    {% else %}

      {% if c.phone_no or c.email %}
        <br>

        {% if c.phone_no %}
          <b>Phone:</b> {{ c.phone_no }}
        {% endif %}

        {% if c.email %}
          <b>Email:</b> {{ c.email }}
        {% endif %}
      {% endif %}

    {% endif %}

  </div>
</div>
